cat << 'EOF' > src/main.rs
use clap::{Arg, ArgAction, Command};
use regex::Regex;
use serde::{Deserialize, Serialize};
use std::env;
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;
use walkdir::WalkDir;

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Plugin {
    name: Option<String>,
    url: Option<String>,
    regex: Option<String>,
    identifier: Option<String>,
    description: Option<String>,
}

struct BuiltinExtractorDef {
    flag_short: char,
    flag_long: &'static str,
    label: &'static str,
    regex_str: &'static str,
}

const BUILTIN_DEFS: &[BuiltinExtractorDef] = &[
    BuiltinExtractorDef {
        flag_short: 'e',
        flag_long: "email",
        label: "email",
        regex_str: r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b",
    },
    BuiltinExtractorDef {
        flag_short: 'p',
        flag_long: "phone",
        label: "phone_number",
        regex_str: r"\b[2-9]\d{2}-\d{3}-\d{4}\b",
    },
    BuiltinExtractorDef {
        flag_short: 'H',
        flag_long: "hash",
        label: "hashes",
        regex_str: r"\b[a-fA-F0-9]{16}\b|\b[a-fA-F0-9]{32}\b|\b[a-fA-F0-9]{40}\b|\b[a-fA-F0-9]{56}\b|\b[a-fA-F0-9]{64}\b|\b[a-fA-F0-9]{96}\b|\b[a-fA-F0-9]{128}\b",
    },
    BuiltinExtractorDef {
        flag_short: 'i',
        flag_long: "ip-addr",
        label: "ip_address",
        regex_str: r"(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\b",
    },
    BuiltinExtractorDef {
        flag_short: '6',
        flag_long: "ipv6-addr",
        label: "ipv6_address",
        regex_str: r"(?i)\b(?:[0-9a-f]{1,4}:){7}[0-9a-f]{1,4}\b|\b(?:[0-9a-f]{1,4}:){1,7}:|\b:(?::[0-9a-f]{1,4}){1,7}\b|\b(?:[0-9a-f]{1,4}:){1,6}:[0-9a-f]{1,4}\b|\b::1\b|\bfe80::1\b",
    },
    BuiltinExtractorDef {
        flag_short: 'm',
        flag_long: "mac-addr",
        label: "mac_address",
        regex_str: r"\b(?:[0-9a-fA-F]{2}:){5}[0-9a-fA-F]{2}\b",
    },
    BuiltinExtractorDef {
        flag_short: 'c',
        flag_long: "credit-card",
        label: "credit_card",
        regex_str: r"\b(?:\d{4}[-\s]?){3}\d{4}\b",
    },
    BuiltinExtractorDef {
        flag_short: 'u',
        flag_long: "url",
        label: "url",
        regex_str: r"https?://[a-zA-Z0-9_\-\.\/~?#@!$&*+=]+",
    },
    BuiltinExtractorDef {
        flag_short: 'F',
        flag_long: "files",
        label: "files",
        regex_str: r"\b[a-zA-Z0-9_-]+\.(?:txt|pdf|doc|xls|csv|png|jpg|jpeg|gif|bmp|zip|tar|gz|7z|rar|py|sh|js|json|xml|exe|dll|log)\b",
    },
    BuiltinExtractorDef {
        flag_short: 'b',
        flag_long: "bitcoin",
        label: "bitcoin_wallet",
        regex_str: r"\b[13][a-km-zA-HJ-NP-Z1-9]{26,33}\b",
    },
    BuiltinExtractorDef {
        flag_short: 'a',
        flag_long: "aws",
        label: "aws_keys",
        regex_str: r"\b(?:aws_access_key_id|aws_secret_access_key)\s*=\s*\S+\b",
    },
    BuiltinExtractorDef {
        flag_short: 'g',
        flag_long: "google",
        label: "google",
        regex_str: r#""private_key_id":\s*"[a-fA-F0-9]{40}""#,
    },
    BuiltinExtractorDef {
        flag_short: 'd',
        flag_long: "dns",
        label: "srv_dns",
        regex_str: r"_[a-zA-Za-0-9_-]+\._[a-zA-Za-0-9_-]+\.[a-zA-Za-0-9_.-]+\s+(?:\d+\s+)?IN\s+SRV\s+\d+\s+\d+\s+\d+\s+[a-zA-Za-0-9_.-]+",
    },
    BuiltinExtractorDef {
        flag_short: 's',
        flag_long: "social",
        label: "social_security",
        regex_str: r"\b\d{3}-\d{2}-\d{4}\b",
    },
];

struct ActiveExtractor {
    label: String,
    re: Regex,
}

fn get_plugin_path() -> PathBuf {
    let home = env::var("HOME").unwrap_or_else(|_| "/root".to_string());
    PathBuf::from(home).join(".DataSurgeon").join("plugins.json")
}

fn main() {
    let start_time = Instant::now();
    let plugin_path = get_plugin_path();

    // Standard startup plugin check
    if !plugin_path.exists() {
        println!(
            "Failed to open plugins.json file. PLUGIN_PATH: {}",
            plugin_path.display()
        );
    }

    let cmd = Command::new("executable")
        .version("1.2.8")
        .before_help("Note: All extraction features (e.g: -i) work on a specified file (-f) or an output stream.\n")
        .arg(
            Arg::new("file")
                .short('f')
                .long("file")
                .value_name("file")
                .help("File to extract information from")
                .default_value(""),
        )
        .arg(
            Arg::new("add")
                .long("add")
                .value_name("add")
                .help("Adds a plugin from a GitHub repository (e.g ds --add https://github.com/Drew-Alleman/ds-winreg-plugin/)")
                .default_value(""),
        )
        .arg(
            Arg::new("update")
                .long("update")
                .value_name("update")
                .help("Updates a plugin from a GitHub repository. You can also use `ds --update all` to update all plugins. (e.g ds --update https://github.com/DataSurgeon-ds/ds-cve-plugin/)")
                .default_value(""),
        )
        .arg(
            Arg::new("remove")
                .long("remove")
                .value_name("remove")
                .help("Removes a plugin from a GitHub repository (e.g ds --remove https://github.com/Drew-Alleman/ds-winreg-plugin/)")
                .default_value(""),
        )
        .arg(
            Arg::new("list")
                .long("list")
                .action(ArgAction::SetTrue)
                .help("List all added plugins"),
        )
        .arg(
            Arg::new("clean")
                .short('C')
                .long("clean")
                .action(ArgAction::SetTrue)
                .help("Only displays the matched result, rather than the entire line"),
        )
        .arg(
            Arg::new("directory")
                .long("directory")
                .value_name("directory")
                .help("Process all files found in the specified directory")
                .default_value(""),
        )
        .arg(
            Arg::new("ignore")
                .long("ignore")
                .action(ArgAction::SetTrue)
                .help("Silences error messages"),
        )
        .arg(
            Arg::new("line")
                .short('l')
                .long("line")
                .action(ArgAction::SetTrue)
                .help("Displays the line number where the match occurred"),
        )
        .arg(
            Arg::new("thorough")
                .short('T')
                .long("thorough")
                .action(ArgAction::SetTrue)
                .help("Doesn't stop at first match (useful for -C if multiple unique matches are on the same line"),
        )
        .arg(
            Arg::new("display")
                .short('D')
                .long("display")
                .action(ArgAction::SetTrue)
                .help("Displays the filename assoicated with the content found (https://github.com/Drew-Alleman/DataSurgeon#reading-all-files-in-a-directory)"),
        )
        .arg(
            Arg::new("suppress")
                .short('S')
                .long("suppress")
                .action(ArgAction::SetTrue)
                .help("Suppress the 'Reading standard input' message when not providing a file"),
        )
        .arg(
            Arg::new("drop")
                .long("drop")
                .value_name("drop")
                .help("Specify a regular expression to exclude certain patterns from the search. (e.g --drop \"^.{1,10}$\" will hide all matches not under 10 characters)")
                .default_value(""),
        )
        .arg(
            Arg::new("filter")
                .long("filter")
                .value_name("filter")
                .help("Include only lines that match the specified regex. (e.g: '--filter ^error' will only include lines that start with the word 'error'")
                .default_value(""),
        )
        .arg(
            Arg::new("hide")
                .short('X')
                .long("hide")
                .action(ArgAction::SetTrue)
                .help("Hides the identifier string infront of the desired content (e.g: 'hash: ', 'url: ', 'email: ' will not be displayed."),
        )
        .arg(
            Arg::new("output")
                .short('o')
                .long("output")
                .value_name("output")
                .help("Output's the results of the procedure to a local file (recommended for large files)")
                .default_value(""),
        )
        .arg(
            Arg::new("time")
                .short('t')
                .long("time")
                .action(ArgAction::SetTrue)
                .help("Time how long the operation took"),
        )
        .arg(
            Arg::new("email")
                .short('e')
                .long("email")
                .action(ArgAction::SetTrue)
                .help("Extract email addresses"),
        )
        .arg(
            Arg::new("phone")
                .short('p')
                .long("phone")
                .action(ArgAction::SetTrue)
                .help("Extracts phone numbers"),
        )
        .arg(
            Arg::new("hash")
                .short('H')
                .long("hash")
                .action(ArgAction::SetTrue)
                .help("Extract hashes (NTLM, LM, bcrypt, Oracle, MD5, SHA-1, SHA-224, SHA-256, SHA-384, SHA-512, SHA3-224, SHA3-256, SHA3-384, SHA3-512, MD4)"),
        )
        .arg(
            Arg::new("ip-addr")
                .short('i')
                .long("ip-addr")
                .action(ArgAction::SetTrue)
                .help("Extract IP addresses"),
        )
        .arg(
            Arg::new("ipv6-addr")
                .short('6')
                .long("ipv6-addr")
                .action(ArgAction::SetTrue)
                .help("Extract IPv6 addresses"),
        )
        .arg(
            Arg::new("mac-addr")
                .short('m')
                .long("mac-addr")
                .action(ArgAction::SetTrue)
                .help("Extract MAC addresses"),
        )
