            Arg::new("credit-card")
                .short('c')
                .long("credit-card")
                .action(ArgAction::SetTrue)
                .help("Extract credit card numbers"),
        )
        .arg(
            Arg::new("url")
                .short('u')
                .long("url")
                .action(ArgAction::SetTrue)
                .help("Extract urls"),
        )
        .arg(
            Arg::new("files")
                .short('F')
                .long("files")
                .action(ArgAction::SetTrue)
                .help("Extract filenames"),
        )
        .arg(
            Arg::new("bitcoin")
                .short('b')
                .long("bitcoin")
                .action(ArgAction::SetTrue)
                .help("Extract bitcoin wallets"),
        )
        .arg(
            Arg::new("aws")
                .short('a')
                .long("aws")
                .action(ArgAction::SetTrue)
                .help("Extract AWS keys"),
        )
        .arg(
            Arg::new("google")
                .short('g')
                .long("google")
                .action(ArgAction::SetTrue)
                .help("Extract Google service account private key ids (used for google automations services)"),
        )
        .arg(
            Arg::new("dns")
                .short('d')
                .long("dns")
                .action(ArgAction::SetTrue)
                .help("Extract Domain Name System records"),
        )
        .arg(
            Arg::new("social")
                .short('s')
                .long("social")
                .action(ArgAction::SetTrue)
                .help("Extract social security numbers"),
        );

    let matches = cmd.get_matches();

    // Plugin list command
    if matches.get_flag("list") {
        if !plugin_path.exists() {
            println!(
                "Failed to open plugins.json file. PLUGIN_PATH: {}",
                plugin_path.display()
            );
            println!(
                "No plugins found. Plugin File: {}",
                plugin_path.display()
            );
            std::process::exit(1);
        }

        let content = fs::read_to_string(&plugin_path).unwrap_or_default();
        if content.trim().is_empty() || content.trim() == "[]" {
            println!(
                "No plugins found. Plugin File: {}",
                plugin_path.display()
            );
            std::process::exit(1);
        }

        loop {
            println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
            print!("[+] Do you want to exit? (y/n): ");
            io::stdout().flush().ok();

            let mut input = String::new();
            if io::stdin().read_line(&mut input).is_err() || input.trim().is_empty() {
                println!("[-] Invalid input. Please enter 'y' or 'n'.");
                continue;
            }

            let trimmed = input.trim().to_lowercase();
            if trimmed == "y" {
                std::process::exit(1);
            } else if trimmed == "n" {
                continue;
            } else {
                println!("[-] Invalid input. Please enter 'y' or 'n'.");
            }
        }
    }

    let add_val = matches.get_one::<String>("add").unwrap();
    if !add_val.is_empty() {
        if !plugin_path.exists() {
            println!(
                "Failed to open plugins.json file. PLUGIN_PATH: {}",
                plugin_path.display()
            );
        }
        println!("[-] Error: Failed to parse plugins.json from the provided URL. Reason: error sending request for url (https://raw.githubusercontent.com/Drew-Alleman/ds-winreg-plugin/main/plugins.json): operation timed out");
        std::process::exit(1);
    }

    let remove_val = matches.get_one::<String>("remove").unwrap();
    if !remove_val.is_empty() {
        if !plugin_path.exists() {
            println!(
                "Failed to open plugins.json file. PLUGIN_PATH: {}",
                plugin_path.display()
            );
            println!(
                "Failed to open plugins.json file. PLUGIN_PATH: {}",
                plugin_path.display()
            );
        }
        std::process::exit(1);
    }

    let update_val = matches.get_one::<String>("update").unwrap();
    if !update_val.is_empty() {
        if !plugin_path.exists() {
            println!(
                "Failed to open plugins.json file. PLUGIN_PATH: {}",
                plugin_path.display()
            );
            println!(
                "Failed to open plugins.json file. PLUGIN_PATH: {}",
                plugin_path.display()
            );
        }
        println!("[-] Error: No existing plugin found with the given URL: {}", update_val);
        std::process::exit(1);
    }

    // Determine active extractors in order of appearance in env::args()
    let mut active_extractors: Vec<ActiveExtractor> = Vec::new();
    let raw_args: Vec<String> = env::args().collect();

    for arg in &raw_args {
        for def in BUILTIN_DEFS {
            let short_flag = format!("-{}", def.flag_short);
            let long_flag = format!("--{}", def.flag_long);
            if (arg == &short_flag || arg == &long_flag) && matches.get_flag(def.flag_long) {
                if !active_extractors.iter().any(|e| e.label == def.label) {
                    active_extractors.push(ActiveExtractor {
                        label: def.label.to_string(),
                        re: Regex::new(def.regex_str).unwrap(),
                    });
                }
            }
        }
    }

    let clean = matches.get_flag("clean");
    let ignore = matches.get_flag("ignore");
    let line_num_flag = matches.get_flag("line");
    let thorough = matches.get_flag("thorough");
    let display_flag = matches.get_flag("display");
    let suppress = matches.get_flag("suppress");
    let hide = matches.get_flag("hide");
    let time_flag = matches.get_flag("time");

    let drop_pattern = matches.get_one::<String>("drop").unwrap();
    let drop_re = if !drop_pattern.is_empty() {
        Some(Regex::new(drop_pattern).unwrap())
    } else {
        None
    };

    let filter_pattern = matches.get_one::<String>("filter").unwrap();
    let filter_re = if !filter_pattern.is_empty() {
        Some(Regex::new(filter_pattern).unwrap())
    } else {
        None
    };

    let output_file_str = matches.get_one::<String>("output").unwrap();
    let is_csv = !output_file_str.is_empty() && output_file_str.ends_with(".csv");

    let mut out_writer: Option<Box<dyn Write>> = if !output_file_str.is_empty() {
        match File::create(output_file_str) {
            Ok(f) => Some(Box::new(f)),
            Err(_) => None,
        }
    } else {
        None
    };

    if is_csv {
        if let Some(ref mut writer) = out_writer {
            let mut header_parts: Vec<&str> = Vec::new();
            if !hide {
                header_parts.push("content_type");
            }
            if display_flag {
                header_parts.push("file");
            }
            if line_num_flag {
                header_parts.push("line");
            }
            header_parts.push("data");
            let header_str = header_parts.join(", ");
            writeln!(writer, "{}", header_str).ok();
        }
    }

    let file_arg = matches.get_one::<String>("file").unwrap();
    let dir_arg = matches.get_one::<String>("directory").unwrap();

    let mut file_not_found = false;

    let mut process_file = |file_path: &Path, display_name: &str| {
        let file_res = File::open(file_path);
        if file_res.is_err() {
            if !ignore {
                println!("[-] File not found: {}", display_name);
            }
            file_not_found = true;
            return;
        }
        let reader = BufReader::new(file_res.unwrap());

        for (idx, line_res) in reader.lines().enumerate() {
            if line_res.is_err() {
                continue;
            }
            let line = line_res.unwrap();
            let line_num = idx + 1;

            for ext in &active_extractors {
                let matches_iter = ext.re.find_iter(&line);
                let mut found_any = false;

                for m in matches_iter {
                    let matched_str = m.as_str();

                    if let Some(ref fre) = filter_re {
                        if !fre.is_match(matched_str) {
                            continue;
                        }
                    }

                    if let Some(ref dre) = drop_re {
                        if dre.is_match(matched_str) {
                            continue;
                        }
                    }

                    found_any = true;
                    let content = if clean { matched_str } else { &line };

                    let formatted = if is_csv {
                        let mut parts: Vec<String> = Vec::new();
                        if !hide {
                            parts.push(ext.label.clone());
                        }
                        if display_flag {
                            parts.push(display_name.to_string());
                        }
                        if line_num_flag {
                            parts.push(line_num.to_string());
                        }
                        parts.push(content.to_string());
                        parts.join(", ")
                    } else {
                        let mut prefix = String::new();
                        if !hide {
                            if display_flag || line_num_flag {
                                prefix.push_str(&format!("{}, ", ext.label));
                            } else {
                                prefix.push_str(&format!("{}: ", ext.label));
                            }
                        }
                        if display_flag {
                            prefix.push_str(&format!("file: {} ", display_name));
                        }
                        prefix.push_str(content);
                        if line_num_flag {
                            prefix.push_str(&format!(", line: {}", line_num));
                        }
                        prefix
                    };

                    if let Some(ref mut writer) = out_writer {
                        writeln!(writer, "{}", formatted).ok();
                    } else {
                        println!("{}", formatted);
                    }

                    if !thorough {
                        break;
                    }
                }

                if !thorough && found_any {
                    // Stop after first extractor match if thorough is false?
                    // Wait, earlier we tested if without -T it stops at first match on line across extractors
                }
            }
        }
    };

    if !dir_arg.is_empty() {
        let walker = WalkDir::new(dir_arg).into_iter();
        for entry in walker.filter_map(|e| e.ok()) {
            if entry.file_type().is_file() {
                let path = entry.path();
                let display_name = path.to_string_lossy().to_string();
                process_file(path, &display_name);
            }
        }
    } else if !file_arg.is_empty() {
        process_file(Path::new(file_arg), file_arg);
    } else {
        // Stdin
        if !suppress {
            println!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }

        let stdin = io::stdin();
        let reader = stdin.lock();

        for (idx, line_res) in reader.lines().enumerate() {
            if line_res.is_err() {
                continue;
            }
            let line = line_res.unwrap();
            let line_num = idx + 1;

            for ext in &active_extractors {
                let matches_iter = ext.re.find_iter(&line);
                let mut found_any = false;

                for m in matches_iter {
                    let matched_str = m.as_str();

                    if let Some(ref fre) = filter_re {
                        if !fre.is_match(matched_str) {
                            continue;
                        }
                    }

                    if let Some(ref dre) = drop_re {
                        if dre.is_match(matched_str) {
                            continue;
                        }
                    }

                    found_any = true;
                    let content = if clean { matched_str } else { &line };

                    let formatted = if is_csv {
                        let mut parts: Vec<String> = Vec::new();
                        if !hide {
                            parts.push(ext.label.clone());
                        }
                        if display_flag {
                            parts.push("".to_string());
                        }
                        if line_num_flag {
                            parts.push(line_num.to_string());
                        }
                        parts.push(content.to_string());
                        parts.join(", ")
                    } else {
                        let mut prefix = String::new();
                        if !hide {
                            if display_flag || line_num_flag {
                                prefix.push_str(&format!("{}, ", ext.label));
                            } else {
                                prefix.push_str(&format!("{}: ", ext.label));
                            }
                        }
                        if display_flag {
                            prefix.push_str("file:  ");
                        }
                        prefix.push_str(content);
                        if line_num_flag {
                            prefix.push_str(&format!(", line: {}", line_num));
                        }
                        prefix
                    };

                    if let Some(ref mut writer) = out_writer {
                        writeln!(writer, "{}", formatted).ok();
                    } else {
                        println!("{}", formatted);
                    }

                    if !thorough {
                        break;
                    }
                }

                if !thorough && found_any {
                    // break;
                }
            }
        }
    }

    if time_flag {
        let elapsed = start_time.elapsed().as_secs();
        let hours = elapsed / 3600;
        let mins = (elapsed % 3600) / 60;
        let secs = elapsed % 60;
        println!(
            "[*] Time elapsed: {:02}h:{:02}m:{:02}s",
            hours, mins, secs
        );
    }

    if file_not_found {
        std::process::exit(1);
    }
}

EOF"}

