                println!("[-] File not found: {}", display_name);
            }
            file_not_found = true;
            return;
        }
        let reader = BufReader::new(file_res.unwrap());

        for (idx, line_res) in reader.lines().enumerate() {
            if line_res.is_err() {
                continue;
            }
            let line = line_res.unwrap();
            let line_num = idx + 1;

            for ext in &active_extractors {
                let matches_iter = ext.re.find_iter(&line);

                for m in matches_iter {
                    let matched_str = m.as_str();

                    if let Some(ref fre) = filter_re {
                        if !fre.is_match(matched_str) {
                            continue;
                        }
                    }

                    if let Some(ref dre) = drop_re {
                        if dre.is_match(matched_str) {
                            continue;
                        }
                    }

                    let content = if clean { matched_str } else { &line };

                    let formatted = if is_csv {
                        let mut parts: Vec<String> = Vec::new();
                        if !hide {
                            parts.push(ext.label.clone());
                        }
                        if display_flag {
                            parts.push(display_name.to_string());
                        }
                        if line_num_flag {
                            parts.push(line_num.to_string());
                        }
                        parts.push(content.to_string());
                        parts.join(", ")
                    } else {
                        let mut prefix = String::new();
                        if !hide {
                            if display_flag || line_num_flag {
                                prefix.push_str(&format!("{}, ", ext.label));
                            } else {
                                prefix.push_str(&format!("{}: ", ext.label));
                            }
                        }
                        if display_flag {
                            prefix.push_str(&format!("file: {} ", display_name));
                        }
                        prefix.push_str(content);
                        if line_num_flag {
                            prefix.push_str(&format!(", line: {}", line_num));
                        }
                        prefix
                    };

                    if let Some(ref mut writer) = out_writer {
                        writeln!(writer, "{}", formatted).ok();
                    } else {
                        println!("{}", formatted);
                    }

                    if !thorough {
                        break;
                    }
                }
            }
        }
    };

    if !dir_arg.is_empty() {
        let walker = WalkDir::new(dir_arg).into_iter();
        for entry in walker.filter_map(|e| e.ok()) {
            if entry.file_type().is_file() {
                let path = entry.path();
                let display_name = path.to_string_lossy().to_string();
                process_file(path, &display_name);
            }
        }
    } else if !file_arg.is_empty() {
        process_file(Path::new(file_arg), file_arg);
    } else {
        // Stdin
        if !suppress {
            println!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }

        let stdin = io::stdin();
        let reader = stdin.lock();

        for (idx, line_res) in reader.lines().enumerate() {
            if line_res.is_err() {
                continue;
            }
            let line = line_res.unwrap();
            let line_num = idx + 1;

            for ext in &active_extractors {
                let matches_iter = ext.re.find_iter(&line);

                for m in matches_iter {
                    let matched_str = m.as_str();

                    if let Some(ref fre) = filter_re {
                        if !fre.is_match(matched_str) {
                            continue;
                        }
                    }

                    if let Some(ref dre) = drop_re {
                        if dre.is_match(matched_str) {
                            continue;
                        }
                    }

                    let content = if clean { matched_str } else { &line };

                    let formatted = if is_csv {
                        let mut parts: Vec<String> = Vec::new();
                        if !hide {
                            parts.push(ext.label.clone());
                        }
                        if display_flag {
                            parts.push("".to_string());
                        }
                        if line_num_flag {
                            parts.push(line_num.to_string());
                        }
                        parts.push(content.to_string());
                        parts.join(", ")
                    } else {
                        let mut prefix = String::new();
                        if !hide {
                            if display_flag || line_num_flag {
                                prefix.push_str(&format!("{}, ", ext.label));
                            } else {
                                prefix.push_str(&format!("{}: ", ext.label));
                            }
                        }
                        if display_flag {
                            prefix.push_str("file:  ");
                        }
                        prefix.push_str(content);
                        if line_num_flag {
                            prefix.push_str(&format!(", line: {}", line_num));
                        }
                        prefix
                    };

                    if let Some(ref mut writer) = out_writer {
                        writeln!(writer, "{}", formatted).ok();
                    } else {
                        println!("{}", formatted);
                    }

                    if !thorough {
                        break;
                    }
                }
            }
        }
    }

    if time_flag {
        let elapsed = start_time.elapsed().as_secs();
        let hours = elapsed / 3600;
        let mins = (elapsed % 3600) / 60;
        let secs = elapsed % 60;
        println!(
            "[*] Time elapsed: {:02}h:{:02}m:{:02}s",
            hours, mins, secs
        );
    }

    if file_not_found {
        std::process::exit(1);
    }
}
EOF"}

